-- Preserve the legacy terms column for old readers. The decision is a snapshot
-- of the fee in force on the subscription's approval date.
BEGIN;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL
);

CREATE TEMP TABLE _pricing_decision_backfill ON COMMIT DROP AS
SELECT s.id AS subscription_id,
       COALESCE(h.fee_cents, (s.terms ->> 'monthlyFeeCents')::integer) AS fee_cents
FROM subscription AS s
LEFT JOIN LATERAL (
  SELECT ph.fee_cents
  FROM pricing_history AS ph
  WHERE ph.subscription_id = s.id
    AND ph.effective_from <= s.approved_at
  ORDER BY ph.effective_from DESC
  LIMIT 1
) AS h ON true;

DO $$
DECLARE
  invalid_count bigint;
  invalid_ids text;
BEGIN
  SELECT count(*), string_agg(subscription_id, ', ' ORDER BY subscription_id)
    INTO invalid_count, invalid_ids
  FROM _pricing_decision_backfill
  WHERE fee_cents IS NULL OR fee_cents < 0
     OR EXISTS (
       SELECT 1 FROM pricing_history AS ph
       WHERE ph.subscription_id = _pricing_decision_backfill.subscription_id
         AND ph.fee_cents < 0
     );

  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'pricing decision backfill refused: % invalid subscription(s): %',
      invalid_count, invalid_ids
      USING ERRCODE = 'P0001', DETAIL = 'Fees must be present and non-negative.';
  END IF;
END
$$;

INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT subscription_id, fee_cents
FROM _pricing_decision_backfill;

ALTER TABLE pricing_decision
  ADD CONSTRAINT pricing_decision_fee_non_negative CHECK (fee_cents >= 0);

COMMIT;

schema.sql:
CREATE TABLE subscription (
  id text PRIMARY KEY,
  approved_at date NOT NULL,
  terms jsonb NOT NULL
);

CREATE TABLE pricing_history (
  subscription_id text REFERENCES subscription(id),
  effective_from date NOT NULL,
  fee_cents integer NOT NULL,
  PRIMARY KEY (subscription_id, effective_from)
);

